using System.Security.Cryptography.X509Certificates;
using System.Text;
using PortableDocument.Core;
using PortableDocument.Document;
using Xunit;

namespace FreeDF.Tests;

/// <summary>
/// Reads files produced by pyHanko 0.38.0 (checked in under tests/fixtures/signatures, regenerated by generate_pyhanko_fixtures.py) and also
/// applies library edits to them, so DocMDP and signature handling is checked against an independent implementation without needing Python.
/// </summary>
public class SignatureInteropTests
{
    static byte[] Fx(string name) => File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory, "fixtures", "signatures", name));

    const string Signer = "pyHanko Fixture Signer";

    static byte[] FillName(byte[] pdf) => DocMdpTests.Update(pdf, (f, ch) =>
    {
        var n = DocMdpTests.Num(f, d => f.Resolve(d.Get("T")) is PdfString { Text: "name" });
        ch[n] = DocMdpTests.With(DocMdpTests.D(f, n), "V", new PdfString(Encoding.Latin1.GetBytes("Grace")));
    });

    [Theory]
    [InlineData("pyhanko-certified-p1.pdf", PdfDocMdpPermission.NoChanges)]
    [InlineData("pyhanko-certified-p2.pdf", PdfDocMdpPermission.FormFillAndSign)]
    public void Reads_pyhanko_certification_signatures(string file, PdfDocMdpPermission p)
    {
        var s = Assert.Single(PdfEditor.VerifySignatures(Fx(file)));
        Assert.True(s.IsCertification);
        Assert.Equal(p, s.DocMdpPermission);
        Assert.Equal(PdfDocMdpStatus.Unmodified, s.DocMdpStatus);
        Assert.Empty(s.DocMdpFindings);
        Assert.True(s.ByteRangeValid && s.DigestValid && s.SignatureValid && s.CoversWholeDocument, s.Error);
        Assert.Equal(Signer, s.SignerName);
        Assert.False(s.ChainTrusted);
    }

    [Fact]
    public void Plain_pyhanko_signature_is_not_a_certification()
    {
        var s = Assert.Single(PdfEditor.VerifySignatures(Fx("pyhanko-signed.pdf")));
        Assert.True(s.SignatureValid, s.Error);
        Assert.False(s.IsCertification);
        Assert.Null(s.DocMdpPermission);
    }

    [Fact]
    public void Pyhanko_approval_after_p2_certification_is_permitted()
    {
        var sigs = PdfEditor.VerifySignatures(Fx("pyhanko-certified-p2-approved.pdf"));
        Assert.Equal(2, sigs.Count);
        Assert.Equal(PdfDocMdpStatus.ChangesPermitted, sigs[0].DocMdpStatus);
        Assert.Empty(sigs[0].DocMdpFindings);
        Assert.True(sigs[0].SignatureValid && sigs[0].ModifiedAfterSigning);
        Assert.True(sigs[1].SignatureValid && sigs[1].CoversWholeDocument && !sigs[1].IsCertification);
    }

    [Fact]
    public void Library_edits_to_pyhanko_certified_files_are_classified()
    {
        using var cert = SecurityTests.Cert("Library Approver");
        // P1: approval signature and form fill are violations; P2: both are permitted.
        var p1 = Fx("pyhanko-certified-p1.pdf");
        Assert.Equal(PdfDocMdpStatus.Violated, PdfEditor.VerifySignatures(PdfEditor.SignFile(p1, new PdfSignOptions { Certificate = cert, FieldName = "A" }))[0].DocMdpStatus);
        Assert.Equal(PdfDocMdpStatus.Violated, PdfEditor.VerifySignatures(FillName(p1))[0].DocMdpStatus);
        var p2 = Fx("pyhanko-certified-p2.pdf");
        Assert.Equal(PdfDocMdpStatus.ChangesPermitted, PdfEditor.VerifySignatures(PdfEditor.SignFile(p2, new PdfSignOptions { Certificate = cert, FieldName = "A" }))[0].DocMdpStatus);
        Assert.Equal(PdfDocMdpStatus.ChangesPermitted, PdfEditor.VerifySignatures(FillName(p2))[0].DocMdpStatus);
        var e = PdfEditor.Open(p2);
        e.SetInfo("Title", "tampered");
        Assert.Equal(PdfDocMdpStatus.Violated, PdfEditor.VerifySignatures(e.SaveIncremental())[0].DocMdpStatus);
    }

    [Fact]
    public void Reads_pyhanko_encrypted_signature()
    {
        var pdf = Fx("pyhanko-encrypted-signed.pdf");
        Assert.Throws<PdfPasswordException>(() => PdfEditor.VerifySignatures(pdf));
        var s = Assert.Single(PdfEditor.VerifySignatures(pdf, "u"));
        Assert.True(s.SignatureValid, s.Error);
        Assert.Equal(Signer, s.SignerName);
    }

    [Fact]
    public void Docmdp_check_works_for_password_protected_certified_files()
    {
        using var cert = SecurityTests.Cert("Library Approver");
        var pdf = Fx("pyhanko-encrypted-certified-p1.pdf");
        var s = Assert.Single(PdfEditor.VerifySignatures(pdf, "u"));
        Assert.True(s.IsCertification && s.SignatureValid, s.Error);
        Assert.Equal(PdfDocMdpStatus.Unmodified, s.DocMdpStatus);

        var approved = PdfEditor.SignFile(pdf, new PdfSignOptions { Certificate = cert, FieldName = "A" }, "u");
        var c = PdfEditor.VerifySignatures(approved, "u")[0];
        Assert.True(c.SignatureValid, c.Error);
        Assert.Equal(PdfDocMdpStatus.Violated, c.DocMdpStatus);
        Assert.NotEmpty(c.DocMdpFindings);

        var e = PdfEditor.Open(pdf, "u");
        e.SetInfo("Title", "tampered");
        Assert.Equal(PdfDocMdpStatus.Violated, PdfEditor.VerifySignatures(e.Sign(new PdfSignOptions { Certificate = cert, FieldName = "B" }), "u")[0].DocMdpStatus);
    }

    [Fact]
    public void Library_certified_password_protected_file_distinguishes_permitted_and_violating_changes()
    {
        using var cert = SecurityTests.Cert("Library Certifier");
        using var approver = SecurityTests.Cert("Library Approver");
        var enc = PdfEditor.Open(DocMdpTests.FormPdf()).Save(options: new PdfWriteOptions { Encryption = new PdfEncryption { UserPassword = "u", OwnerPassword = "o" } });
        foreach (var (p, status) in new[] { (PdfDocMdpPermission.NoChanges, PdfDocMdpStatus.Violated), (PdfDocMdpPermission.FormFillAndSign, PdfDocMdpStatus.ChangesPermitted) })
        {
            var certified = PdfEditor.SignFile(enc, new PdfSignOptions { Certificate = cert, FieldName = "Certify", Certify = p }, "u");
            var first = Assert.Single(PdfEditor.VerifySignatures(certified, "u"));
            Assert.Equal(PdfDocMdpStatus.Unmodified, first.DocMdpStatus);
            Assert.True(first.SignatureValid, first.Error);
            var two = PdfEditor.SignFile(certified, new PdfSignOptions { Certificate = approver, FieldName = "Approve" }, "u");
            Assert.Equal(status, PdfEditor.VerifySignatures(two, "u")[0].DocMdpStatus);
        }
    }

    [Fact]
    public void Reads_pyhanko_document_timestamp()
    {
        var sigs = PdfEditor.VerifySignatures(Fx("pyhanko-doctimestamp.pdf"));
        Assert.Equal(2, sigs.Count);
        Assert.True(sigs[0].SignatureValid && !sigs[0].IsDocumentTimeStamp);
        var ts = sigs[1];
        Assert.True(ts.IsDocumentTimeStamp);
        Assert.Equal("ETSI.RFC3161", ts.SubFilter);
        Assert.True(ts.ByteRangeValid && ts.DigestValid && ts.SignatureValid, ts.Error);
        // pyHanko appended a validation-info (DSS) update after the timestamp, as in an LTA workflow.
        Assert.True(ts.ModifiedAfterSigning);
        Assert.NotNull(PdfEditor.ReadDocumentSecurityStore(Fx("pyhanko-doctimestamp.pdf")));
        Assert.NotNull(ts.TimeStampTime);
        Assert.Equal("pyHanko Fixture TSA", ts.SignerName);
    }

    [Fact]
    public void Reads_pyhanko_pades_signature_and_dss()
    {
        var pdf = Fx("pyhanko-pades-dss.pdf");
        var s = Assert.Single(PdfEditor.VerifySignatures(pdf));
        Assert.Equal("ETSI.CAdES.detached", s.SubFilter);
        Assert.True(s.SignatureValid, s.Error);
        var dss = PdfEditor.ReadDocumentSecurityStore(pdf);
        Assert.NotNull(dss);
        Assert.True(dss!.Certificates >= 1);
        Assert.True(s.HasValidationInformation);
    }

    /// <summary>
    /// Library-produced files (tests/fixtures/signatures/lib) that pyHanko 0.38.0 validated; see lib/pyhanko-0.38.0-results.txt for its verdicts.
    /// pyHanko docmdp_ok=False must correspond to Violated here, True to Unmodified or ChangesPermitted.
    /// </summary>
    [Theory]
    [InlineData("certified-p1.pdf", PdfDocMdpStatus.Unmodified, false)]
    [InlineData("certified-p1-approved.pdf", PdfDocMdpStatus.Violated, false)]
    [InlineData("certified-p1-filled.pdf", PdfDocMdpStatus.Violated, false)]
    [InlineData("certified-p1-dss.pdf", PdfDocMdpStatus.ChangesPermitted, false)]
    [InlineData("certified-p2-approved.pdf", PdfDocMdpStatus.ChangesPermitted, false)]
    [InlineData("certified-p2-filled.pdf", PdfDocMdpStatus.ChangesPermitted, false)]
    [InlineData("certified-p3-filled.pdf", PdfDocMdpStatus.ChangesPermitted, false)]
    [InlineData("encrypted-certified-p2-approved.pdf", PdfDocMdpStatus.ChangesPermitted, true)]
    public void Library_produced_fixtures_match_the_verdicts_pyhanko_gave(string file, PdfDocMdpStatus expected, bool encrypted)
    {
        var sigs = PdfEditor.VerifySignatures(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory, "fixtures", "signatures", "lib", file)), encrypted ? "u" : "");
        Assert.All(sigs, s => Assert.True(s.SignatureValid, s.Error));
        Assert.Equal(expected, sigs[0].DocMdpStatus);
    }

    [Fact]
    public void Library_produced_timestamp_and_encrypted_signature_fixtures_verify()
    {
        string P(string n) => Path.Combine(AppContext.BaseDirectory, "fixtures", "signatures", "lib", n);
        var ts = PdfEditor.VerifySignatures(File.ReadAllBytes(P("doctimestamp.pdf")));
        Assert.True(ts[1].IsDocumentTimeStamp && ts[1].SignatureValid && ts[1].CoversWholeDocument, ts[1].Error);
        Assert.True(Assert.Single(PdfEditor.VerifySignatures(File.ReadAllBytes(P("encrypted-incremental-signed.pdf")), "u")).SignatureValid);
    }
}
